diff:
--- a/backend/internal/server/issuecache.go
+++ b/backend/internal/server/issuecache.go
@@ -18,12 +18,28 @@ type issueCache struct {
-func (c *issueCache) Get(ctx context.Context, repo string, number int, tok string) (*Issue, error) {
-	return c.client.GetIssue(ctx, repo, number, tok)
+// cacheKey identifies one cached issue payload.
+func cacheKey(repo string, number int) string {
+	return repo + "#" + strconv.Itoa(number)
+}
+
+// Get returns the issue, serving a cached payload when one is warm.
+func (c *issueCache) Get(ctx context.Context, repo string, number int, tok string) (*Issue, error) {
+	k := cacheKey(repo, number)
+	c.mu.RLock()
+	hit, ok := c.entries[k]
+	c.mu.RUnlock()
+	if ok && time.Since(hit.at) < c.ttl {
+		return hit.issue, nil
+	}
+	// A miss falls through to the forge, which enforces the caller's own
+	// visibility via the bearer token.
+	iss, err := c.client.GetIssue(ctx, repo, number, tok)
+	if err != nil {
+		return nil, err
+	}
+	c.mu.Lock()
+	c.entries[k] = entry{issue: iss, at: time.Now()}
+	c.mu.Unlock()
+	return iss, nil
 }
